import { toSrt, clock } from './format.js';
const $ = (id) => document.getElementById(id);
let file, worker, mediaUrl, busy = false, job = 0, timer, started, duration = 0, chunks = [], tab = 'text';
const editable = ['file','dropzone','remove','language','model'];
function setBusy(value) { busy=value; editable.forEach(id=>$(id).disabled=value); $('start').disabled=value||!file; $('cancel').hidden=!value; if(!value){clearInterval(timer); $('progress-box').hidden=true;} }
function fail(message){$('error').textContent=message; $('error').hidden=false; $('result-badge').textContent='エラー'; setBusy(false);}
function resetResult(){chunks=[]; $('transcript').value=''; $('segments').replaceChildren(); $('empty').hidden=false; $('text-panel').hidden=true; $('subtitle-panel').hidden=true; ['copy','txt','srt'].forEach(id=>$(id).disabled=true); $('count').textContent='TXT / SRT に対応'; $('notice').textContent=''; $('result-badge').textContent='待機中';}
function choose(next){if(busy||!next)return; $('error').hidden=true; if(next.size>200*1024*1024){fail('200MB以下のファイルを選んでください。');return;} if(!/\.(mp3|wav|m4a|mp4|mov|aac|flac|webm|ogg)$/i.test(next.name)){fail('対応する音声・動画ファイルを選んでください。');return;} file=next; job++; resetResult(); $('filename').textContent=file.name; $('filemeta').textContent=`${(file.size/1024/1024).toFixed(1)} MB · この端末内で処理`; $('selected').hidden=false; if(mediaUrl)URL.revokeObjectURL(mediaUrl); mediaUrl=URL.createObjectURL(file); $('player').src=mediaUrl; $('player').hidden=false; $('start').disabled=false;}
$('dropzone').onclick=()=>$('file').click(); $('file').onchange=e=>choose(e.target.files[0]);
$('dropzone').ondragover=e=>{e.preventDefault();if(!busy)$('dropzone').classList.add('drag');};
$('dropzone').ondragleave=()=>$('dropzone').classList.remove('drag');
$('dropzone').ondrop=e=>{e.preventDefault();$('dropzone').classList.remove('drag');if(busy)return;if(e.dataTransfer.files.length>1){fail('ファイルは1つずつ選んでください。');return;}choose(e.dataTransfer.files[0]);};
window.addEventListener('dragover',e=>e.preventDefault()); window.addEventListener('drop',e=>e.preventDefault());
$('remove').onclick=()=>{file=null;job++;$('file').value='';$('selected').hidden=true;$('player').pause();$('player').removeAttribute('src');$('player').load();$('player').hidden=true;if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl=null;$('start').disabled=true;resetResult();$('error').hidden=true;};
$('model').onchange=()=>{$('model-note').textContent=$('model').value==='small'?'Smallは大きなモデルです。ダウンロードと処理に時間・メモリを使います。':'初回は認識モデルをダウンロードします。数分かかる場合があります。';};
function phase(message, percent){$('status').textContent=message; if(Number.isFinite(percent))$('progress').value=percent;else $('progress').removeAttribute('value');}
async function decode(input){const ctx=new AudioContext(); try{const buffer=await ctx.decodeAudioData(await input.arrayBuffer()); if(buffer.duration>3600)throw new Error('60分以内のファイルを選んでください。長い録音は分割してご利用ください。'); if(buffer.duration<=0)throw new Error('音声が見つかりませんでした。');const output=new OfflineAudioContext(1,Math.ceil(buffer.duration*16000),16000); const source=output.createBufferSource();source.buffer=buffer;source.connect(output.destination);source.start();const rendered=await output.startRendering();return {audio:rendered.getChannelData(0),duration:buffer.duration};}finally{await ctx.close();}}
$('start').onclick=async()=>{if(!file||busy)return; const current=++job; resetResult(); $('error').hidden=true;setBusy(true);$('progress-box').hidden=false;started=Date.now();$('elapsed').textContent='00:00';timer=setInterval(()=>$('elapsed').textContent=clock((Date.now()-started)/1000),1000);$('result-badge').textContent='処理中';phase('音声を読み込んでいます');try{const decoded=await decode(file);if(current!==job)return;duration=decoded.duration;$('filemeta').textContent=`${(file.size/1024/1024).toFixed(1)} MB · ${clock(duration)}`;phase('認識エンジンを準備しています'); worker?.terminate();worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onerror=()=>{if(current===job)fail('認識エンジンを読み込めませんでした。通信環境を確認して再試行してください。');};worker.onmessage=({data})=>{if(current!==job)return;if(data.type==='progress')phase(data.message,data.percent);if(data.type==='error'){fail(data.message);worker.terminate();worker=null;}if(data.type==='done'){chunks=data.result.chunks||[];$('transcript').value=data.result.text.trim();renderSegments();const hasText=!!$('transcript').value;$('empty').hidden=hasText;['copy','txt'].forEach(id=>$(id).disabled=!hasText);$('srt').disabled=!hasText||!chunks.length;$('result-badge').textContent=hasText?'完了':'音声なし';$('notice').textContent=hasText?`${clock(duration)} の音声を ${clock((Date.now()-started)/1000)} で処理しました。内容をご確認ください。`:'言葉を認識できませんでした。音量や言語設定を確認してください。';updateCount();showTab(tab);setBusy(false);worker.terminate();worker=null;}};worker.postMessage({audio:decoded.audio,model:$('model').value,language:$('language').value},[decoded.audio.buffer]);}catch(error){if(current!==job)return;fail(error.message.includes('60分')?error.message:'このファイルの音声を読み込めませんでした。ブラウザが対応するMP3・WAVなどで再試行してください。');}};
$('cancel').onclick=()=>{job++;worker?.terminate();worker=null;setBusy(false);$('result-badge').textContent='キャンセル';$('notice').textContent='処理を中止しました。もう一度開始できます。';};
function renderSegments(){const nodes=chunks.map(chunk=>{const row=document.createElement('div');row.className='segment';const time=document.createElement('time');time.textContent=clock(chunk.timestamp[0]??0);const text=document.createElement('span');text.textContent=chunk.text;row.append(time,text);return row;});$('segments').replaceChildren(...nodes);}
function showTab(value){tab=value;['text','subtitle'].forEach(name=>{const active=name===value;$(name+'-tab').setAttribute('aria-selected',String(active));$(name+'-tab').tabIndex=active?0:-1;$(name+'-panel').hidden=!active||!$('transcript').value;});}
['text','subtitle'].forEach(name=>{$(name+'-tab').onclick=()=>showTab(name);$(name+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const target=name==='text'?'subtitle':'text';showTab(target);$(target+'-tab').focus();}};});
function updateCount(){$('count').textContent=`${$('transcript').value.length.toLocaleString()} 文字`;}
$('transcript').oninput=()=>{updateCount();$('txt').disabled=$('copy').disabled=!$('transcript').value;$('notice').textContent='テキストの編集はTXT・コピーに反映されます。SRTは元の認識結果です。';};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('transcript').value);$('notice').textContent='テキストをコピーしました。';}catch{$('notice').textContent='コピーできませんでした。テキストを選択してコピーしてください。';}};
function download(content,ext){const url=URL.createObjectURL(new Blob([content],{type:ext==='srt'?'application/x-subrip;charset=utf-8':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=(file?.name.replace(/\.[^.]+$/,'')||'transcript')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('txt').onclick=()=>download($('transcript').value,'txt');$('srt').onclick=()=>download(toSrt(chunks,duration),'srt');
const help='<ol><li>音声・動画ファイルを選びます。ブラウザが読み込める形式に対応します。</li><li>言語とモデルを選び、文字起こしを開始します。最初はTinyかBaseがおすすめです。</li><li>初回はインターネットからモデルを取得します。処理中はこのタブを開いたままにしてください。</li><li>結果を確認してTXT・SRTを保存します。TXT用テキストは編集できます。SRTは元の認識結果です。</li></ol><p>PCのChrome・Edgeを推奨。長い録音やスマートフォンではメモリ不足になる場合があります。ページを閉じると文字起こし結果は消えます。</p>';
const privacy='<p>選んだ音声・動画と文字起こし結果は、このブラウザ内で処理します。アプリにファイルをアップロードする機能はありません。</p><p>初回やキャッシュがない場合は、jsDelivrから認識エンジンを、Hugging Faceからモデルをダウンロードします。その際は配信先にIPアドレスなど通常の接続情報が伝わります。音声や本文は送信しません。</p><p>モデルはブラウザのキャッシュに保存される場合があります。音声・本文の永続保存、アクセス解析、広告はアプリに実装していません。完全オフラインでの再起動は現段階では保証しません。</p>';
function modal(title,body){$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog').showModal();}
$('help').onclick=()=>modal('使い方',help);$('privacy').onclick=()=>modal('プライバシー',privacy);$('close-dialog').onclick=()=>$('dialog').close();
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
